import React, { useState } from "react";

function App() {
  const [query, setQuery] = useState("");
  const [summary, setSummary] = useState("");
  const [publications, setPublications] = useState([]);
  const [clinicalTrials, setClinicalTrials] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = async () => {
    if (!query.trim()) return;

    try {
      setLoading(true);
      setError("");

      const res = await fetch("http://localhost:5000/api/query", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({ query })
      });

      const data = await res.json();

      setSummary(data.summary || "");
      setPublications(data.publications || []);
      setClinicalTrials(data.clinical_trials || []);

    } catch (err) {
      console.error(err);
      setError("Failed to fetch medical research data.");
    } finally {
      setLoading(false);
    }
  };

  const handleDownloadPDF = async () => {
    try {
      const res = await fetch("http://localhost:8000/generate-pdf", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          query,
          summary,
          publications,
          clinical_trials: clinicalTrials
        })
      });

      const blob = await res.blob();
      const url = window.URL.createObjectURL(blob);

      const a = document.createElement("a");
      a.href = url;
      a.download = "medical_report.pdf";
      a.click();

      window.URL.revokeObjectURL(url);

    } catch (err) {
      console.error("PDF Download Failed:", err);
    }
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.heading}>AI Medical Research Assistant</h1>

      <div style={styles.searchBox}>
        <input
          type="text"
          placeholder="Ask medical research query..."
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          style={styles.input}
        />

        <button onClick={handleSubmit} style={styles.button}>
          {loading ? "Searching..." : "Search"}
        </button>
      </div>

      {error && <p style={styles.error}>{error}</p>}

      {(publications.length > 0 || clinicalTrials.length > 0) && (
        <button onClick={handleDownloadPDF} style={styles.pdfButton}>
          Download Research Report PDF
        </button>
      )}

      {summary && (
        <div style={styles.summaryBox}>
          <h2>AI Summary</h2>
          <p>{summary}</p>
        </div>
      )}

      {publications.length > 0 && (
        <>
          <h2 style={styles.sectionTitle}>Research Publications</h2>

          <div style={styles.results}>
            {publications.map((pub, index) => (
              <div key={index} style={styles.card}>
                <h3>{pub.title}</h3>

                <p style={styles.meta}>
                  {pub.authors?.join(", ")}
                  {pub.year ? ` • ${pub.year}` : ""}
                </p>

                <p>{pub.abstract || "No abstract available."}</p>

                <a href={pub.link} target="_blank" rel="noreferrer" style={styles.link}>
                  View Full Publication →
                </a>
              </div>
            ))}
          </div>
        </>
      )}

      {clinicalTrials.length > 0 && (
        <>
          <h2 style={styles.sectionTitle}>Clinical Trials</h2>

          <div style={styles.results}>
            {clinicalTrials.map((trial, index) => (
              <div key={index} style={styles.card}>
                <h3>{trial.title}</h3>

                <p style={styles.meta}>
                  Phase: {trial.phase || "N/A"}
                </p>

                <a href={trial.link} target="_blank" rel="noreferrer" style={styles.link}>
                  View Clinical Trial →
                </a>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

const styles = {
  container: {
    padding: "40px",
    fontFamily: "Arial",
    background: "#f7f9fc",
    minHeight: "100vh"
  },

  heading: {
    marginBottom: "25px"
  },

  searchBox: {
    display: "flex",
    gap: "10px",
    marginBottom: "30px"
  },

  input: {
    flex: 1,
    padding: "14px",
    fontSize: "16px",
    borderRadius: "8px",
    border: "1px solid #ccc"
  },

  button: {
    padding: "14px 24px",
    background: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
    fontWeight: "bold"
  },

  pdfButton: {
    padding: "12px 22px",
    background: "#28a745",
    color: "white",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
    fontWeight: "bold",
    marginBottom: "30px"
  },

  error: {
    color: "red",
    marginBottom: "20px"
  },

  summaryBox: {
    background: "#eef5ff",
    padding: "20px",
    borderRadius: "14px",
    marginBottom: "30px",
    boxShadow: "0 4px 12px rgba(0,0,0,0.06)"
  },

  sectionTitle: {
    marginTop: "40px",
    marginBottom: "20px"
  },

  results: {
    display: "grid",
    gap: "20px"
  },

  card: {
    background: "white",
    padding: "24px",
    borderRadius: "14px",
    boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
  },

  meta: {
    color: "#666",
    fontSize: "14px",
    marginBottom: "12px"
  },

  link: {
    display: "inline-block",
    marginTop: "14px",
    color: "#007bff",
    textDecoration: "none",
    fontWeight: "bold"
  }
};

export default App;
